(({F:e})=>{e.push({code:"sv",week:{dow:1,doy:4},prevText:"Förra",nextText:"Nästa",todayText:"Idag",yearText:"År",monthText:"Månad",weekTextLong:"Vecka",weekTextShort:"v.",dayText:"Dag",listText:"Program",prevHint(e){return"Föregående "+e.toLocaleLowerCase()},nextHint(e){return"Nästa "+e.toLocaleLowerCase()},todayHint(e,t){return("year"===t?"I":"Denna")+" "+e.toLocaleLowerCase()},viewHint:"$0 vy",navLinkHint:"Gå till $0",moreLinkHint(e){return`Visa ytterligare ${e} händelse`+(1===e?"":"r")},allDayText:"Heldag",moreLinkText:"till",noEventsText:"Inga händelser att visa",closeHint:"Stäng",eventsHint:"Händelser"})})(FullCalendar.Shared);